const form=document.getElementById("taxForm"),result=document.getElementById("result");form&&form.addEventListener("submit",e=>{e.preventDefault();const l=parseFloat(document.getElementById("income").value)||0,n=parseFloat(document.getElementById("rate").value)||.04,s=document.getElementById("period").value==="year"?12:1,t=l*s,a=t*n,o=24e5,c=t>o,m=Math.max(0,t-o);result.innerHTML=`
      <div class="result-list">
        <div class="item"><span>Доход за период</span><span class="val">${fmt(t)} ₽</span></div>
        <div class="item"><span>Ставка</span><span class="val">${Math.round(n*100)}%</span></div>
        <div class="item total"><span>Налог</span><span class="val">${fmt(a)} ₽</span></div>
      </div>
      ${c?`<p class="hint" style="margin-top:14px;color:#c0392b">
             ⚠️ Доход превышает лимит НПД (2 400 000 ₽/год) на ${fmt(m)} ₽.
             Часть, свыше лимита, облагается по другой системе налогообложения.
           </p>`:`<p class="hint" style="margin-top:14px">≈ ${fmt(a/s)} ₽ налога в месяц при таком доходе.</p>`}
    `;const i=document.getElementById("printHint");i&&(i.hidden=!1)});function fmt(e){return new Intl.NumberFormat("ru-RU",{maximumFractionDigits:2}).format(e)}
